export {HARNESS_TOOLS,HARNESS_BUILTINS,harnessGoalSchema,harnessSkillSchema,harnessConfigSchema,harnessTaskSchema,harnessIdentitySchema,harnessGoalProgress,validateHarnessPlan} from './business-harness-schema';

export const BUSINESS_HARNESS_SCOPE='Tenant-scoped confirmed business memory and selected read tools. Goal numbers are manually entered; unknown revenue, conversion, rankings and benchmarks stay unknown. AI plans and experiments are drafts. Only an explicitly reviewed internal task can be saved; no messages, public posts, payments or calendar changes are made.';
const permission="EXISTS(SELECT 1 FROM agent_memberships m JOIN agent_tenants t ON t.id=m.tenant_id WHERE m.tenant_id=? AND m.user_id=? AND m.status='active' AND t.status='active' AND m.role IN ('owner','manager') AND (m.expires_at IS NULL OR m.expires_at>?))";
const configSelect='SELECT * FROM mayor_harness_configs WHERE tenant_id=? AND user_id=?';
const sourceSentence=(value:string)=>/[.!?]$/.test(value.trim())?value.trim():value.trim()+'.';
function profileSourceDetail(profile:Record<string,unknown>){
 const labels:Record<string,string>={name:'Business name',assistantName:'Assistant name',industry:'Industry',services:'Services',locations:'Locations',hours:'Business hours',staff:'Staff',timeZone:'Time zone',website:'Website',businessGoals:'Business goals',bottlenecks:'Bottlenecks',currentTools:'Current tools',growthPlan:'Growth plan'};
 return Object.entries(profile).map(([key,value])=>{
  const raw=key.replace(/([A-Z])/g,' $1').toLowerCase(),label=labels[key]??raw[0].toUpperCase()+raw.slice(1);
  const detail=Array.isArray(value)?value.length?value.join('; '):key==='staff'?'no staff':'none confirmed':value&&typeof value==='object'?JSON.stringify(value):String(value);
  return sourceSentence(`${label}: ${detail}`);
 }).join(' ')||'No confirmed business profile is available.';
}
type GoalRow={id:string;tenant_id:string;title:string;description:string;metric_json:string|null;deadline:string|null;archived:number;revision:number};
type SkillRow={id:string;tenant_id:string;title:string;instructions:string;allowed_tools_json:string;archived:number;revision:number};
type ConfigRow={tenant_id:string;user_id:string;goal_ids_json:string;skill_ids_json:string;connector_options_json:string;schedule_json:string|null;enabled:number;revision:number;next_run_at:string|null;due_local_date:string|null;lease_token:string|null;lease_until:string|null;last_run_at:string|null;last_status:string|null};
type RunRow={id:string;tenant_id:string;user_id:string;config_revision:number;data_revision:number;memory_revision:number;dedupe_key:string;trigger_kind:'manual'|'scheduled';state:'processing'|'ready'|'failed'|'blocked'|'canceled';lease_token:string|null;lease_until:string|null;report_json:string|null;error_code:string|null;reply_attempt_counted:number;model_started_at:string|null;created_at:string;updated_at:string};
type ProposalRow={id:string;tenant_id:string;user_id:string;kind:'goal'|'skill'|'config'|'task'|'identity';input_json:string;state:'pending'|'confirmed';expires_at:string;created_at:string};
type IdentityInput=z.infer<typeof harnessIdentitySchema>;
export type HarnessProposal={readonly id:string;readonly expiresAt:string;readonly readback:string;readonly requiresUiReview:boolean;readonly input:HarnessGoalInput|HarnessSkillInput|HarnessConfigInput|HarnessTaskInput|IdentityInput};
type ToolTrace={tool:string;status:'completed'|'unavailable'|'skipped';detail:string};
export type BusinessHarnessReport={id:string;generatedAt:string;summary:string;goalProgress:{goalId:string;title:string;metric:ReturnType<typeof goalView>['metric'];progress:number|null;source:'manual_entry'}[];metrics:{key:string;label:string;value:number|null}[];sources:{id:string;kind:string;detail:string}[];priorities:HarnessPlan['priorities'];taskDrafts:(HarnessPlan['taskDrafts'][number]&{id:string;dueAt:null;customerId:null;acceptedTaskId:string|null})[];experiments:(HarnessPlan['experiments'][number]&{id:string})[];toolTrace:ToolTrace[];gaps:string[];scope:string};
type HarnessAuthorization={grantId:string;provider:OAuthProvider;userId:string;accountId:string;revision:number;grantedScopes:string;selectedCapabilities:string;calendarId?:string;policyRevision?:number};
export type HarnessContext={checkedAt:string;dates:string[];openTasks:{id:string;title:string}[];profile:Record<string,unknown>;identity:Awaited<ReturnType<typeof readHarnessIdentity>>;goals:ReturnType<typeof goalView>[];skills:{id:string;title:string;instructions:string;allowedTools:HarnessTool[]}[];sources:{id:string;kind:string;detail:string}[];metrics:BusinessHarnessReport['metrics'];gaps:string[];toolTrace:ToolTrace[];memoryRevision:number;dataRevision:number;authorizations:HarnessAuthorization[]};
/** alreadyMetered is internal-only for a currently authorized chat turn; never an HTTP field. */
export type HarnessRunOptions={now?:number;infer?:(env:Env,context:HarnessContext)=>Promise<unknown>;claim?:typeof claimUsage;transport?:typeof fetch;actor?:Actor;alreadyMetered?:boolean};
const goalView=(row:GoalRow)=>({id:row.id,revision:row.revision,title:row.title,description:row.description,metric:row.metric_json?JSON.parse(row.metric_json) as {baseline:number;current:number;target:number;unit:string}:null,deadline:row.deadline,archived:Boolean(row.archived)});
const skillView=(row:SkillRow)=>({id:row.id,revision:row.revision,title:row.title,instructions:row.instructions,allowedTools:JSON.parse(row.allowed_tools_json) as HarnessTool[],archived:Boolean(row.archived)});
const runView=(row:RunRow)=>({id:row.id,status:row.state==='processing'&&(!row.lease_until||row.lease_until<=new Date().toISOString())?'failed' as const:row.state,trigger:row.trigger_kind,createdAt:row.created_at,updatedAt:row.updated_at,errorCode:row.state==='processing'&&(!row.lease_until||row.lease_until<=new Date().toISOString())?'interrupted_attempt':row.error_code,replyAttemptCounted:Boolean(row.reply_attempt_counted)});
function configView(row:ConfigRow|null){return {revision:row?.revision??0,enabled:Boolean(row?.enabled),goalIds:row?JSON.parse(row.goal_ids_json) as string[]:[],skillIds:row?JSON.parse(row.skill_ids_json) as string[]:['builtin:daily-priorities'],connectorOptions:row?JSON.parse(row.connector_options_json):{},schedule:row?.schedule_json?JSON.parse(row.schedule_json):null,nextRunAt:row?.next_run_at??null,lastRunAt:row?.last_run_at??null,lastStatus:row?.last_status??null,running:Boolean(row?.lease_until&&row.lease_until>new Date().toISOString())};}
async function ensureState(env:Env,actor:Actor){await requireMembership(env,actor,OPERATORS);const now=new Date().toISOString();await env.AGENT_DB.prepare(`INSERT INTO mayor_harness_state(tenant_id,revision) SELECT ?,0 WHERE ${permission} ON CONFLICT(tenant_id) DO NOTHING`).bind(actor.tenantId,actor.tenantId,actor.userId,now).run();}
async function sharedRecords(env:Env,actor:Actor){await requireMembership(env,actor,OPERATORS);const [goals,skills,state]=await env.AGENT_DB.batch([env.AGENT_DB.prepare('SELECT * FROM mayor_harness_goals WHERE tenant_id=? ORDER BY archived,title,id LIMIT 60').bind(actor.tenantId),env.AGENT_DB.prepare('SELECT * FROM mayor_harness_skills WHERE tenant_id=? ORDER BY archived,title,id LIMIT 60').bind(actor.tenantId),env.AGENT_DB.prepare('SELECT revision FROM mayor_harness_state WHERE tenant_id=?').bind(actor.tenantId)]);await requireMembership(env,actor,OPERATORS);return {goals:(goals.results as GoalRow[]).map(goalView),skills:(skills.results as SkillRow[]).map(skillView),revision:(state.results[0] as {revision:number}|undefined)?.revision??0};}
async function connectorView(env:Env,actor:Actor){const [gmail,selection,scheduling]=await Promise.all([gmailConnections(env,actor),selectedCalendar(env,actor),readSchedulingPolicy(env,actor)]);await requireMembership(env,actor,OPERATORS);return {gmail,calendar:{available:Boolean(selection?.available&&scheduling.policy),timeZone:scheduling.policy?.timeZone??null,appointmentTypes:scheduling.policy?.appointmentTypes.map(type=>({name:type.name,staff:scheduling.policy!.staff.filter(item=>item.appointmentTypes.includes(type.name)).map(item=>item.name)}))??[],scope:'Explicitly selected live openings only; no imported event details, automatic booking or held slots.'}};}
async function reportWithActions(env:Env,actor:Actor,row:RunRow|null){if(!row?.report_json)return null;const report=JSON.parse(row.report_json) as BusinessHarnessReport,accepted=await env.AGENT_DB.prepare('SELECT draft_id,task_id FROM mayor_harness_task_acceptances WHERE tenant_id=? AND user_id=? AND run_id=?').bind(actor.tenantId,actor.userId,row.id).all<{draft_id:string;task_id:string}>();return {...report,taskDrafts:report.taskDrafts.map(draft=>({...draft,acceptedTaskId:accepted.results.find(item=>item.draft_id===draft.id)?.task_id??null}))};}
export async function readBusinessHarness(env:Env,actor:Actor){
 await requireMembership(env,actor,OPERATORS);const [shared,config,runs,connectors,identity]=await Promise.all([sharedRecords(env,actor),env.AGENT_DB.prepare(configSelect).bind(actor.tenantId,actor.userId).first<ConfigRow>(),env.AGENT_DB.prepare('SELECT * FROM mayor_harness_runs WHERE tenant_id=? AND user_id=? ORDER BY updated_at DESC,id DESC LIMIT 10').bind(actor.tenantId,actor.userId).all<RunRow>(),connectorView(env,actor),readHarnessIdentity(env,actor)]);const latest=await env.AGENT_DB.prepare("SELECT * FROM mayor_harness_runs WHERE tenant_id=? AND user_id=? AND state='ready' ORDER BY updated_at DESC,id DESC LIMIT 1").bind(actor.tenantId,actor.userId).first<RunRow>();const latestReport=await reportWithActions(env,actor,latest);await requireMembership(env,actor,OPERATORS);return {agent:{id:actor.tenantId,label:'Business agent'},goals:shared.goals,skills:shared.skills,builtins:HARNESS_BUILTINS,allowedTools:HARNESS_TOOLS,config:configView(config),latestReport,history:runs.results.map(runView),connectors,identity,scope:BUSINESS_HARNESS_SCOPE};
}
function selectedSkills(shared:Awaited<ReturnType<typeof sharedRecords>>,ids:string[]){return ids.map(id=>{const value=HARNESS_BUILTINS.find(item=>item.id===id)??shared.skills.find(item=>item.id===id&&!item.archived);if(!value)throw new HttpError(409,'harness_skill_changed','A selected skill is unavailable. Review your agent settings.');return value;});}
async function validateConfiguration(env:Env,actor:Actor,input:HarnessConfigInput){const shared=await sharedRecords(env,actor),skills=selectedSkills(shared,input.skillIds);if(input.goalIds.some(id=>!shared.goals.some(goal=>goal.id===id&&!goal.archived)))throw new HttpError(409,'harness_goal_changed','A selected goal is unavailable. Review your agent settings.');const tools=new Set(skills.flatMap(skill=>skill.allowedTools));if(tools.has('gmail_unread')&&!input.connectorOptions.gmailGrantId)throw new HttpError(400,'harness_gmail_choice_required','Explicitly choose your connected Gmail account before scheduling unread header reads.');if(tools.has('calendar_openings')&&!input.connectorOptions.calendar)throw new HttpError(400,'harness_calendar_choice_required','Explicitly choose a confirmed appointment type before scheduling calendar reads.');if(tools.has('gmail_unread')||tools.has('calendar_openings')){const connectors=await connectorView(env,actor);if(tools.has('gmail_unread')&&(!connectors.gmail.available||!connectors.gmail.connections.some(item=>item.grantId===input.connectorOptions.gmailGrantId&&item.status==='authorized')))throw new HttpError(409,'harness_gmail_unavailable','Your selected Gmail read access is unavailable.');if(tools.has('calendar_openings')){const type=connectors.calendar.appointmentTypes.find(item=>item.name===input.connectorOptions.calendar?.appointmentType),staff=input.connectorOptions.calendar?.staff;if(!connectors.calendar.available||!type||type.staff.length&&!type.staff.includes(staff??'')||!type.staff.length&&staff)throw new HttpError(409,'harness_calendar_unavailable','Choose an available calendar, confirmed service and required staff member.');}}return shared.revision;}
async function prepareRecord(env:Env,actor:Actor,kind:ProposalRow['kind'],raw:unknown):Promise<HarnessProposal>{await ensureState(env,actor);let input:HarnessProposal['input'];if(kind==='goal')input={...harnessGoalSchema.parse(raw),id:harnessGoalSchema.parse(raw).id??crypto.randomUUID()};else if(kind==='skill')input={...harnessSkillSchema.parse(raw),id:harnessSkillSchema.parse(raw).id??crypto.randomUUID()};else if(kind==='identity')input=harnessIdentitySchema.parse(raw);else if(kind==='config'){input=harnessConfigSchema.parse(raw);await validateConfiguration(env,actor,input);}else{input=harnessTaskSchema.parse(raw);await taskDraft(env,actor,input.runId,input.draftId);if(input.customerId&&!await env.AGENT_DB.prepare('SELECT id FROM mayor_customers WHERE id=? AND tenant_id=?').bind(input.customerId,actor.tenantId).first())throw new HttpError(404,'customer_unavailable','Choose a saved customer from this business.');}
 const id=crypto.randomUUID(),now=new Date().toISOString(),expiresAt=new Date(Date.now()+120000).toISOString(),fullReadback=await proposalReadback(env,actor,kind,input),requiresUiReview=fullReadback.length>3500,readback=requiresUiReview?'These changes are too long to verify aloud. Open the agent settings on Today and review every field before saving. No voice confirmation is armed.':fullReadback,result=await env.AGENT_DB.prepare(`INSERT INTO mayor_harness_proposals(id,tenant_id,user_id,kind,input_json,state,expires_at,created_at) SELECT ?,?,?,?,?,'pending',?,? WHERE ${permission}`).bind(id,actor.tenantId,actor.userId,kind,JSON.stringify(input),expiresAt,now,actor.tenantId,actor.userId,now).run();if(!result.meta.changes)throw new HttpError(409,'harness_access_changed','Your access changed. Review again.');return {id,expiresAt,readback,requiresUiReview,input};
}
async function proposalReadback(env:Env,actor:Actor,kind:ProposalRow['kind'],input:HarnessProposal['input']){
 if(kind==='goal'){const goal=input as HarnessGoalInput;return `${goal.archived?'Archive':'Save'} goal “${goal.title}”. Description: ${sourceSentence(goal.description||'none')} Manual metric: ${goal.metric?`baseline ${goal.metric.baseline}, current ${goal.metric.current}, target ${goal.metric.target}, unit ${goal.metric.unit}`:'none'}. Deadline: ${goal.deadline??'none'}. Say yes to confirm these values.`;}
 if(kind==='skill'){const skill=input as HarnessSkillInput;return `${skill.archived?'Archive':'Save'} skill “${skill.title}”. Planning instructions, quoted as preferences: “${skill.instructions}”. Allowed read tools: ${skill.allowedTools.join(', ')}. These cannot authorize sends, publishing, payments, calendar changes or executable code. Say yes to confirm.`;}
 if(kind==='identity'){const identity=input as IdentityInput;return `Save agent preferences. Mission: ${sourceSentence(identity.mission||'none')} Tone: ${identity.tone}. Principles: ${sourceSentence(identity.principles.join('; ')||'none')} Working style: ${sourceSentence(identity.workingStyle||'none')} These preferences never override tool permissions or safety rules. Say yes to confirm.`;}
 if(kind==='config'){const config=input as HarnessConfigInput,shared=await sharedRecords(env,actor),skills=selectedSkills(shared,config.skillIds),schedule=config.schedule;return `Save selected goals: ${config.goalIds.map(id=>shared.goals.find(goal=>goal.id===id)?.title??id).join('; ')||'none'}. Skills: ${skills.map(skill=>skill.title).join('; ')}. Allowed read tools: ${[...new Set(skills.flatMap(skill=>skill.allowedTools))].join(', ')}. Schedule: ${config.enabled&&schedule?`${schedule.frequency==='daily'?'daily':'Monday through Friday'} at ${String(schedule.hour).padStart(2,'0')}:${String(schedule.minute).padStart(2,'0')} ${schedule.timeZone}`:'paused'}. Gmail: ${config.connectorOptions.gmailGrantId?'the explicitly selected owned Gmail grant; unread subject headers only':'no mailbox selected'}. Calendar: ${config.connectorOptions.calendar?`${config.connectorOptions.calendar.appointmentType}, staff ${config.connectorOptions.calendar.staff??'none'}, next 24-hour openings only`:'no live opening read selected'}. Each actual AI run uses one shared reply attempt. Outputs remain drafts; no sends, public posts, payments or calendar changes. Say yes to confirm.`;}
 const task=input as HarnessTaskInput,customer=task.customerId?await env.AGENT_DB.prepare('SELECT name FROM mayor_customers WHERE id=? AND tenant_id=?').bind(task.customerId,actor.tenantId).first<{name:string}>():null;return `Save internal task “${task.title}”, ${task.priority} priority, due ${task.dueAt??'not set'}, customer ${customer?.name??'none'}. Nothing will be sent or booked. Say yes to confirm.`;
}
export const prepareHarnessGoal=(env:Env,actor:Actor,input:unknown)=>prepareRecord(env,actor,'goal',input);
export const prepareHarnessSkill=(env:Env,actor:Actor,input:unknown)=>prepareRecord(env,actor,'skill',input);
export const prepareHarnessConfig=(env:Env,actor:Actor,input:unknown)=>prepareRecord(env,actor,'config',input);
export const prepareHarnessTask=(env:Env,actor:Actor,input:unknown)=>prepareRecord(env,actor,'task',input);
export const prepareHarnessIdentity=(env:Env,actor:Actor,input:unknown)=>prepareRecord(env,actor,'identity',input);
async function proposalRow(env:Env,actor:Actor,id:string,kind:ProposalRow['kind']){z.uuid().parse(id);await requireMembership(env,actor,OPERATORS);const row=await env.AGENT_DB.prepare('SELECT * FROM mayor_harness_proposals WHERE id=? AND tenant_id=? AND user_id=? AND kind=?').bind(id,actor.tenantId,actor.userId,kind).first<ProposalRow>();if(!row||row.state==='pending'&&row.expires_at<=new Date().toISOString())throw new HttpError(409,'confirmation_expired','Review these details again before confirming.');return row;}
const proposalGuard="EXISTS(SELECT 1 FROM mayor_harness_proposals WHERE id=? AND tenant_id=? AND user_id=? AND kind=? AND state='pending' AND expires_at>?)";
async function saveGoalOrSkill(env:Env,actor:Actor,row:ProposalRow){const goal=row.kind==='goal',input=goal?harnessGoalSchema.parse(JSON.parse(row.input_json)):harnessSkillSchema.parse(JSON.parse(row.input_json)),id=input.id!,now=new Date().toISOString(),table=goal?'mayor_harness_goals':'mayor_harness_skills';const prior=await env.AGENT_DB.prepare(`SELECT * FROM ${table} WHERE id=? AND tenant_id=?`).bind(id,actor.tenantId).first<GoalRow&SkillRow>();const values=goal?[input.title,(input as HarnessGoalInput).description,(input as HarnessGoalInput).metric?JSON.stringify((input as HarnessGoalInput).metric):null,(input as HarnessGoalInput).deadline??null,Number(input.archived)]:[input.title,(input as HarnessSkillInput).instructions,JSON.stringify((input as HarnessSkillInput).allowedTools),Number(input.archived)];const priorValues=prior?(goal?[prior.title,prior.description,prior.metric_json,prior.deadline,prior.archived]:[prior.title,prior.instructions,prior.allowed_tools_json,prior.archived]):null;
 if(prior&&prior.revision===input.revision+1&&JSON.stringify(priorValues)===JSON.stringify(values)){await requireMembership(env,actor,OPERATORS);return;}
 if((prior?.revision??0)!==input.revision||prior?.tenant_id&&prior.tenant_id!==actor.tenantId)throw new HttpError(409,'harness_record_changed','This saved record changed. Review its current version.');
 const columns=goal?'title,description,metric_json,deadline,archived':'title,instructions,allowed_tools_json,archived',assign=columns.split(',').map(name=>`${name}=excluded.${name}`).join(','),result=await env.AGENT_DB.batch([env.AGENT_DB.prepare(`INSERT INTO ${table}(id,tenant_id,${columns},revision,created_by,updated_by,created_at,updated_at) SELECT ?,?,${values.map(()=>'?').join(',')},1,?,?,?,? WHERE ${permission} AND ${proposalGuard} AND COALESCE((SELECT revision FROM ${table} WHERE id=? AND tenant_id=?),0)=? AND (EXISTS(SELECT 1 FROM ${table} WHERE id=? AND tenant_id=?) OR (SELECT COUNT(*) FROM ${table} WHERE tenant_id=?)<60) AND (?=1 OR EXISTS(SELECT 1 FROM ${table} WHERE id=? AND tenant_id=? AND archived=0) OR (SELECT COUNT(*) FROM ${table} WHERE tenant_id=? AND archived=0)<20) ON CONFLICT(id) DO UPDATE SET ${assign},revision=${table}.revision+1,updated_by=excluded.updated_by,updated_at=excluded.updated_at WHERE ${table}.tenant_id=excluded.tenant_id AND ${table}.revision=?`).bind(id,actor.tenantId,...values,actor.userId,actor.userId,now,now,actor.tenantId,actor.userId,now,row.id,actor.tenantId,actor.userId,row.kind,now,id,actor.tenantId,input.revision,id,actor.tenantId,actor.tenantId,Number(input.archived),id,actor.tenantId,actor.tenantId,input.revision),env.AGENT_DB.prepare('UPDATE mayor_harness_state SET revision=revision+1 WHERE tenant_id=? AND changes()=1').bind(actor.tenantId)]);if(result[0].meta.changes!==1)throw new HttpError(409,'harness_record_changed','This record, saved record limit (60 total, 20 active), or your access changed. Refresh and review again.');
}
async function saveConfig(env:Env,actor:Actor,row:ProposalRow){const input=harnessConfigSchema.parse(JSON.parse(row.input_json)),dataRevision=await validateConfiguration(env,actor,input),prior=await env.AGENT_DB.prepare(configSelect).bind(actor.tenantId,actor.userId).first<ConfigRow>(),now=new Date().toISOString(),schedule=input.schedule??(prior?.schedule_json?checkScheduleSchema.parse(JSON.parse(prior.schedule_json)):null),next=input.enabled?nextCheckRun(schedule!,Date.now()):null;
 const same=prior&&prior.revision===input.revision+1&&Boolean(prior.enabled)===input.enabled&&prior.goal_ids_json===JSON.stringify(input.goalIds)&&prior.skill_ids_json===JSON.stringify(input.skillIds)&&prior.connector_options_json===JSON.stringify(input.connectorOptions)&&prior.schedule_json===(schedule?JSON.stringify(schedule):null);if(same)return;
 const result=await env.AGENT_DB.prepare(`INSERT INTO mayor_harness_configs(tenant_id,user_id,enabled,goal_ids_json,skill_ids_json,connector_options_json,schedule_json,revision,next_run_at,due_local_date,created_at,updated_at) SELECT ?,?,?,?,?,?,?,1,?,?,?,? WHERE ${permission} AND ${proposalGuard} AND COALESCE((SELECT revision FROM mayor_harness_configs WHERE tenant_id=? AND user_id=?),0)=? AND EXISTS(SELECT 1 FROM mayor_harness_state WHERE tenant_id=? AND revision=?) ON CONFLICT(tenant_id,user_id) DO UPDATE SET enabled=excluded.enabled,goal_ids_json=excluded.goal_ids_json,skill_ids_json=excluded.skill_ids_json,connector_options_json=excluded.connector_options_json,schedule_json=excluded.schedule_json,revision=mayor_harness_configs.revision+1,next_run_at=excluded.next_run_at,due_local_date=excluded.due_local_date,lease_token=NULL,lease_until=NULL,updated_at=excluded.updated_at WHERE mayor_harness_configs.revision=?`).bind(actor.tenantId,actor.userId,Number(input.enabled),JSON.stringify(input.goalIds),JSON.stringify(input.skillIds),JSON.stringify(input.connectorOptions),schedule?JSON.stringify(schedule):null,next?.at??null,next?.date??null,now,now,actor.tenantId,actor.userId,now,row.id,actor.tenantId,actor.userId,'config',now,actor.tenantId,actor.userId,input.revision,actor.tenantId,dataRevision,input.revision).run();if(result.meta.changes!==1)throw new HttpError(409,'harness_config_changed','Agent settings, saved goals/skills or your access changed. Review again.');
}
export async function readHarnessIdentity(env:Env,actor:Actor){await requireMembership(env,actor,KNOWLEDGE_ROLES);const [row,memory]=await Promise.all([env.AGENT_DB.prepare('SELECT mission,tone,principles_json,working_style,revision FROM mayor_harness_identity WHERE tenant_id=?').bind(actor.tenantId).first<{mission:string;tone:'warm'|'professional'|'direct';principles_json:string;working_style:string;revision:number}>(),readMemory(env,actor)]);await requireMembership(env,actor,KNOWLEDGE_ROLES);return {revision:row?.revision??0,displayName:memory.profile.assistantName??'Mayor',mission:row?.mission??'',tone:row?.tone??'warm',principles:row?JSON.parse(row.principles_json) as string[]:[],workingStyle:row?.working_style??''};}
