async function confirmRecord(env:Env,actor:Actor,proposal:Pick<HarnessProposal,'id'>,kind:ProposalRow['kind']){const row=await proposalRow(env,actor,proposal.id,kind);if(row.state!=='confirmed'){if(kind==='config')await saveConfig(env,actor,row);else if(kind==='identity')await saveIdentity(env,actor,row);else await saveGoalOrSkill(env,actor,row);await env.AGENT_DB.prepare(`UPDATE mayor_harness_proposals SET state='confirmed' WHERE id=? AND tenant_id=? AND user_id=? AND ${permission}`).bind(row.id,actor.tenantId,actor.userId,actor.tenantId,actor.userId,new Date().toISOString()).run();}return readBusinessHarness(env,actor);}
