async function taskIdFor(actor:Actor,input:HarnessTaskInput){const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(`${actor.tenantId}:${actor.userId}:${input.runId}:${input.draftId}`)),hex=Array.from(new Uint8Array(digest),byte=>byte.toString(16).padStart(2,'0')).join('');return `${hex.slice(0,8)}-${hex.slice(8,12)}-4${hex.slice(13,16)}-8${hex.slice(17,20)}-${hex.slice(20,32)}`;}
