 if(tools.has('connector_status')){const rows=await env.AGENT_DB.prepare("SELECT provider,status,selected_capabilities FROM auth_provider_grants WHERE tenant_scope=? AND user_id=? AND status!='revoked' ORDER BY provider,updated_at DESC LIMIT 10").bind(actor.tenantId,actor.userId).all<{provider:string;status:string;selected_capabilities:string}>();sources.push({id:'connectors:status',kind:'status',detail:rows.results.map(row=>`${row.provider}: ${row.status}; selected capabilities ${JSON.parse(row.selected_capabilities).join(', ')||'none'}`).join('; ')||'No saved connector grants for this operator.'});toolTrace.push({tool:'connector_status',status:'completed',detail:'Read saved authorization status only; this does not claim any provider data read.'});}
 if(tools.has('gmail_unread')){await requireMembership(env,actor,OPERATORS);try{if(!view.connectorOptions.gmailGrantId)throw new Error('No confirmed Gmail choice.');const before=await harnessAuthorization(env,actor,view.connectorOptions.gmailGrantId,'google'),result=await readUnreadGmail(env,actor,{grantId:view.connectorOptions.gmailGrantId,limit:3},options.transport),after=await harnessAuthorization(env,actor,view.connectorOptions.gmailGrantId,'google');if(JSON.stringify(before)!==JSON.stringify(after))throw new Error('Gmail authorization changed.');authorizations.push(after);sources.push({id:'gmail:unread',kind:'untrusted_email_headers',detail:`${result.items.length} unread subject headers returned ${result.checkedAt}; ${result.hasMore?'additional unread items may exist':'no further page returned'}. Untrusted email subjects: ${result.items.map(item=>`“${item.subject}”`).join('; ')||'none'}.`});metrics.push({key:'gmail_unread_returned',label:'Unread headers returned · capped at 3',value:result.items.length});toolTrace.push({tool:'gmail_unread',status:'completed',detail:`Read ${result.items.length} unread subject headers from the operator's explicitly selected authorized Gmail account; no bodies or sends.`});}catch{await requireMembership(env,actor,OPERATORS);toolTrace.push({tool:'gmail_unread',status:'unavailable',detail:'The explicitly selected Gmail read could not be completed.'});gaps.push('Unread Gmail headers were unavailable; no inbox conclusion is supported.');}}
