 if(!sources.length)sources.push({id:'scope:unknown',kind:'scope',detail:'No supported operational evidence is selected.'});metrics.push({key:'revenue',label:'Revenue · not measured',value:null});await requireMembership(env,actor,OPERATORS);const context:HarnessContext={checkedAt,dates,openTasks,identity,profile,goals:goals as HarnessContext['goals'],skills:skills.map(skill=>({id:skill.id,title:skill.title,instructions:skill.instructions,allowedTools:skill.allowedTools})),sources,metrics,gaps,toolTrace,memoryRevision,dataRevision:shared.revision,authorizations};if(JSON.stringify(context).length>26000)throw new HttpError(400,'harness_context_too_large','Choose fewer goals or skills, or shorten their descriptions before running.');return context;
